## Code Example

```javascript
function threeWayQuicksort(arr, left=0, right=arr.length-1) {
  if (left >= right) return;
  const pivot = arr[Math.floor((left + right) / 2)];
  let lt = left, i = left, gt = right;
  while (i <= gt) {
    if (arr[i] < pivot) { [arr[lt], arr[i]] = [arr[i], arr[lt]]; lt++; i++; }
    else if (arr[i] > pivot) { [arr[i], arr[gt]] = [arr[gt], arr[i]]; gt--; }
    else { i++; }
  }
  threeWayQuicksort(arr, left, lt - 1);
  threeWayQuicksort(arr, gt + 1, right);
}
```

